package com.metalurgica.sistemagestaoindustrial.service;

import com.metalurgica.sistemagestaoindustrial.domain.*; import com.metalurgica.sistemagestaoindustrial.importacao.*; import com.metalurgica.sistemagestaoindustrial.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.stream.*;

@Service public class ImportacaoValidator {
 private final EmpresaService empresaService; private final SetorRepository setorRepository; private final FuncionarioRepository funcionarioRepository; private final PecaRepository pecaRepository; private final MaquinaRepository maquinaRepository; private final TurnoRepository turnoRepository; private final RegistroProducaoRepository producaoRepository;
 public ImportacaoValidator(EmpresaService e,SetorRepository s,FuncionarioRepository f,PecaRepository p,MaquinaRepository m,TurnoRepository t,RegistroProducaoRepository r){empresaService=e;setorRepository=s;funcionarioRepository=f;pecaRepository=p;maquinaRepository=m;turnoRepository=t;producaoRepository=r;}
 @Transactional(readOnly=true) public ValidacaoImportacaoResult validate(Long empresaId,Long setorId,ExcelReadResult input){empresaService.find(empresaId);var setor=setorRepository.findByIdAndEmpresaId(setorId,empresaId).orElseThrow(()->new com.metalurgica.sistemagestaoindustrial.exception.ResourceNotFoundException("Setor não encontrado nesta empresa."));var errors=new ArrayList<>(input.erros());var rows=input.linhas();var funcs=funcionarioRepository.findByEmpresaIdAndCodigoIn(empresaId,rows.stream().map(r->code(r.codigoFuncionario())).collect(Collectors.toSet())).stream().collect(Collectors.toMap(f->code(f.getCodigo()),f->f,(a,b)->a));var pecas=pecaRepository.findByEmpresaIdAndCodigoIn(empresaId,rows.stream().map(r->code(r.codigoPeca())).collect(Collectors.toSet())).stream().collect(Collectors.toMap(p->code(p.getCodigo()),p->p,(a,b)->a));var maquinas=maquinaRepository.findByEmpresaIdAndCodigoIn(empresaId,rows.stream().map(r->code(r.codigoMaquina())).filter(Objects::nonNull).collect(Collectors.toSet())).stream().collect(Collectors.toMap(m->code(m.getCodigo()),m->m,(a,b)->a));var turnos=turnoRepository.findByEmpresaIdAndCodigoIn(empresaId,rows.stream().map(r->code(r.codigoTurno())).filter(Objects::nonNull).collect(Collectors.toSet())).stream().collect(Collectors.toMap(t->code(t.getCodigo()),t->t,(a,b)->a));var valid=new ArrayList<LinhaValidadaImportacao>();var signatures=new HashMap<String,Integer>();var byEmployee=new HashMap<Long,List<LinhaValidadaImportacao>>();for(var row:rows){var func=funcs.get(code(row.codigoFuncionario()));var peca=pecas.get(code(row.codigoPeca()));boolean bad=false;if(func==null){errors.add(err(row,"codigoFuncionario","FUNCIONARIO_NAO_ENCONTRADO","Funcionário não encontrado."));bad=true;}else if(!func.isAtivo()){errors.add(err(row,"codigoFuncionario","FUNCIONARIO_INATIVO","Funcionário inativo."));bad=true;}if(peca==null){errors.add(err(row,"codigoPeca","PECA_NAO_ENCONTRADA","Peça não encontrada."));bad=true;}else if(!peca.isAtivo()){errors.add(err(row,"codigoPeca","PECA_INATIVA","Peça inativa."));bad=true;}if(row.setor()!=null&&!row.setor().isBlank()&&!code(row.setor()).equals(code(setor.getCodigo()))&&!code(row.setor()).equals(code(setor.getNome()))){errors.add(err(row,"setor","SETOR_DIVERGENTE","Setor da linha diverge do contexto."));bad=true;}var machine=row.codigoMaquina()==null||row.codigoMaquina().isBlank()?null:maquinas.get(code(row.codigoMaquina()));if(row.codigoMaquina()!=null&&!row.codigoMaquina().isBlank()&&(machine==null||!machine.isAtivo())){errors.add(err(row,"maquina","MAQUINA_NAO_ENCONTRADA","Máquina não encontrada ou inativa."));bad=true;}else if(machine!=null&&!machine.getSetor().getId().equals(setorId)){errors.add(err(row,"maquina","MAQUINA_SETOR_INVALIDO","Máquina pertence a outro setor."));bad=true;}var shift=row.codigoTurno()==null||row.codigoTurno().isBlank()?null:turnos.get(code(row.codigoTurno()));if(row.codigoTurno()!=null&&!row.codigoTurno().isBlank()&&(shift==null||!shift.isAtivo())){errors.add(err(row,"turno","TURNO_NAO_ENCONTRADO","Turno não encontrado ou inativo."));bad=true;}var start=row.inicioDateTime();var end=row.fimDateTime(row.fim().isBefore(row.inicio()));if(start==null||end==null||!end.isAfter(start)){errors.add(err(row,"periodo","PERIODO_INVALIDO","Período inválido."));bad=true;}if(!bad){String sig=code(row.codigoFuncionario())+"|"+code(row.codigoPeca())+"|"+row.quantidade()+"|"+start+"|"+end;if(signatures.containsKey(sig)){errors.add(err(row,"linha","LINHA_DUPLICADA","Linha duplicada da linha "+signatures.get(sig)+"."));bad=true;}else signatures.put(sig,row.linha());if(producaoRepository.existsOverlapping(func.getId(),start,end,null)){errors.add(err(row,"periodo","SOBREPOSICAO","Período sobreposto a uma produção existente."));bad=true;}var line=new LinhaValidadaImportacao(row,func,peca,machine,shift,start,end);for(var prior:byEmployee.getOrDefault(func.getId(),List.of()))if(prior.inicio().isBefore(end)&&prior.fim().isAfter(start)){errors.add(err(row,"periodo","SOBREPOSICAO","Período sobreposto à linha "+prior.linha().linha()+"."));bad=true;}if(!bad){valid.add(line);byEmployee.computeIfAbsent(func.getId(),k->new ArrayList<>()).add(line);}}
  }return new ValidacaoImportacaoResult(valid,errors,input.totalLinhas());}
 private static ImportacaoLinhaErro err(LinhaProducaoImportada r,String f,String c,String m){return new ImportacaoLinhaErro(r.linha(),f,c,m,r.codigoFuncionario(),r.codigoPeca());}private static String code(String s){return s==null?null:EmpresaService.normalizeText(s).toUpperCase(Locale.ROOT);}
}
